
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_m11_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_m11_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.847807679077426e+00, -5.801487731774986e+00, -5.719970286927379e+00, -5.573774553148093e+00, -5.310719652800725e+00, -4.848794249665918e+00, -4.093015179770746e+00, -3.021896321086033e+00, -1.896334542173252e+00, -1.288056752428896e+00, -9.106610008652388e-01, -6.749420912306627e-01, -6.261770611672351e-01, -4.984361863861543e-01, -3.994637116953138e-01, -3.175265480662395e-01, -2.284604157940817e-01, -1.791580891607848e-01, -4.379373273401969e-02, -4.952793325611485e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


